<?php
require __DIR__.'/../vendor/autoload.php';$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use App\Models\User;use App\Http\Controllers\PortalController;use App\Services\Workspace;
function r($u,$v=[]){$r=Illuminate\Http\Request::create('/','POST',$v);$r->headers->set('Accept','application/json');$r->setUserResolver(fn()=>$u);return $r;}function ok($v,$s){if(!$v)throw new RuntimeException($s);echo "PASS: $s\n";}function denied($fn,$code){try{$fn();throw new RuntimeException('Expected denial');}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){ok($e->getStatusCode()===$code,'Permission / time boundary enforced');}}
DB::beginTransaction();try{$suffix=Str::uuid();$a=User::create(['name'=>'Activity QA','email'=>$suffix.'@example.test','password'=>'test-password123','role'=>'salesperson']);$b=User::create(['name'=>'Other QA','email'=>'b'.$suffix.'@example.test','password'=>'test-password123','role'=>'salesperson']);$admin=User::create(['name'=>'Admin QA','email'=>'c'.$suffix.'@example.test','password'=>'test-password123','role'=>'admin']);$p=new PortalController;$w=new Workspace;
$id=$p->workday(r($a))['id'];ok($p->workday(r($a))['id']===$id,'Starting twice reuses active workday');ok($p->currentWorkday(r($a))['workday']->id===$id,'Current workday belongs to signed-in user');ok(!$p->currentWorkday(r($b))['workday'],'Another salesperson cannot resume this workday');
$point=['submission_key'=>(string)Str::uuid(),'latitude'=>-1.2921,'longitude'=>36.8219,'accuracy_m'=>12,'recorded_at'=>now()->utc()->toISOString()];$p->locations(r($a,['points'=>[$point]]),$id);$p->locations(r($a,['points'=>[$point]]),$id);ok(DB::table('location_points')->where('workday_id',$id)->count()===1,'GPS retries store one point');ok(count($p->route(r($admin),$id))===1,'Admin can inspect saved route');ok($p->route(r($admin,['page'=>1]),$id)['total']===1,'Admin route pagination returns bounded points');ok($w->records(r($admin,['salesperson_id'=>$a->id,'date'=>now()->toDateString()]),'payments')['total']===0,'Payment activity filtering queries assigned owner safely');denied(fn()=>$p->route(r($b),$id),403);denied(fn()=>$p->locations(r($b,['points'=>[$point]]),$id),403);
$client=DB::table('clients')->insertGetId(['salesperson_id'=>$a->id,'name'=>'Activity QA client','contact'=>'QA','location'=>'Nairobi','created_at'=>now(),'updated_at'=>now()]);$report=$p->record(r($a,['submission_key'=>(string)Str::uuid(),'date'=>now()->toDateString(),'follow_up_date'=>now()->addDay()->toDateString(),'client_id'=>$client,'notes'=>'Follow up tomorrow']),'reports')->getData(true)['id'];ok(DB::table('reports')->where('id',$report)->value('follow_up_date')===now()->addDay()->toDateString(),'Daily report saves follow-up date');$page=$w->records(r($admin,['salesperson_id'=>$a->id,'date'=>now()->toDateString()]),'reports');ok(count($page['records'])===1&&$page['records'][0]->salesperson_name==='Activity QA','Admin filters daily reports with salesperson name');ok($w->records(r($b,['salesperson_id'=>$a->id]),'reports')['total']===0,'Salesperson filter cannot bypass ownership');ok($w->detail(r($admin),'clients',$client)['record']->salesperson_name==='Activity QA','Client detail identifies responsible salesperson');$p->review(r($admin,['status'=>'approved']),'reports',$report);ok(DB::table('reports')->where('id',$report)->value('status')==='approved','Admin approves staff daily report');$p->endWorkday(r($a),$id);ok(!$p->currentWorkday(r($a))['workday'],'Ending stops active workday');$late=[...$point,'submission_key'=>(string)Str::uuid(),'recorded_at'=>now()->addMinute()->utc()->toISOString()];denied(fn()=>$p->locations(r($a,['points'=>[$late]]),$id),422);
}finally{DB::rollBack();}echo "Activity fixtures rolled back.\n";
